    spec = _parse(expr)
    return (when.minute in spec.minutes
            and when.hour in spec.hours
            and when.month in spec.months
            and spec.day_ok(when.date()))


def next_run(expr, after):
    """The first run of expr strictly after the datetime after, or None."""
    spec = _parse(expr)
    try:
        start = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    except OverflowError:
        return None
    try:
        limit = after + _SEARCH_LIMIT
    except OverflowError:
        limit = datetime.max

    hours = sorted(spec.hours)
    minutes = sorted(spec.minutes)
    day = start.date()
    last_day = limit.date()
    while day <= last_day:
        if day.month in spec.months and spec.day_ok(day):
            for hour in hours:
                for minute in minutes:
                    run = datetime(day.year, day.month, day.day, hour, minute)
                    if run < start:
                        continue
                    if run > limit:
                        return None
                    return run
        if day == date.max:
            break
        day += timedelta(days=1)
    return None
